  'tips-p4' => 'Փաստաթղթերի տարբեր տեսակների համար AI ամփոփման տեխնիկայի մանրամասն նկարագրության համար տես ուղեցույցը __AI_SUMMARY_GUIDE_LINK__-ում:',
  'notright-heading' => 'Երբ AI ամփոփումը ճիշտ գործիք չէ',
  'notright-p1' => 'AI-ի ամփոփումը լավ է աշխատում փաստացի, կառուցվածքային բովանդակության համար: Այն ավելի քիչ լավ է աշխատում այն ​​փաստաթղթերի համար, որտեղ կարևոր են նրբերանգները, տոնայնությունը և կոնկրետ ձևակերպումները: Իրավական փաստաթղթերը, որտեղ ճշգրիտ պայմանագրային լեզուն կարևոր է, պետք է վերանայվեն որակավորված մասնագետի կողմից, այլ ոչ թե ամփոփվեն AI-ի կողմից: Ակադեմիական աշխատությունները, որտեղ մեթոդաբանության մանրամասները նույնքան կարևոր են, որքան եզրակացությունները, պետք է ուշադիր կարդալ, քան ամփոփել:',
  'notright-p2' => 'Փաստաթղթերի համար, որտեղ դուք պետք է խորապես հասկանաք բովանդակությունը, այլ ոչ թե պարզապես կորզեք հիմնական կետերը, AI ամփոփումը օգտակար է որպես առաջին անցում, բայց չպետք է փոխարինի ընթերցանությանը: Օգտագործեք այն երկար փաստաթղթում կողմնորոշվելու համար, նախքան ձեզ համար առավել համապատասխան բաժինները կարդալը:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-p1' => 'AI PDF-ի ամփոփումը 2026թ.-ին գիտելիքի աշխատողների համար AI-ի գործնականորեն առավել օգտակար հավելվածներից մեկն է: Այն 90 րոպեանոց ընթերցանության առաջադրանքը վերածում է 5 րոպեանոց վերանայման, և որակը բավական լավ է շատ մասնագիտական ​​նպատակների համար, երբ օգտագործվում է փաստացի, կառուցվածքային փաստաթղթերի համար:',
  'conclusion-p2' => 'Սկսեք __SUMMARIZE_LINK__-ից PDFTools-ում՝ առանց գրանցման արագ, անվճար ամփոփման համար: Ավելի բարդ կարիքների համար ChatGPT Plus-ը և Google Gemini-ն առաջարկում են խոսակցական հետևում, որը թույլ է տալիս փաստաթղթից հանել հենց այն, ինչ ձեզ անհրաժեշտ է: AI-ի ամփոփման գործիքների ամբողջական համեմատության համար տե՛ս __BEST_AI_TOOLS_LINK__:',
  'faq-heading' => 'Հաճախակի տրվող հարցեր',
  'faq1-q' => 'Որքանո՞վ են ճշգրիտ AI PDF ամփոփագրերը:',
  'faq1-a' => 'Լավ կառուցված փաստական ​​փաստաթղթերի համար, ընդհանուր առմամբ, ճշգրտությունը բարձր է: Արհեստական ​​ինտելեկտը հուսալիորեն ընդգրկում է հիմնական եզրակացությունները, հիմնական վիճակագրությունը և առաջնային փաստարկները: Բարդ փաստարկներով, խիստ որակավորված հայտարարություններով կամ փաստաթղթի ավելի վաղ համատեքստից կախված բովանդակություն ունեցող փաստաթղթերի դեպքում սխալներն ավելի հաճախ են տեղի ունենում: Միշտ ստուգեք աղբյուրի դեմ կարևոր պնդումները:',
  'faq2-q' => 'Կարո՞ղ է AI-ն ամփոփել սկանավորված PDF-ները:',
  'faq2-a' => 'Ոչ ուղղակիորեն, քանի որ սկանավորված PDF-ները պարունակում են ոչ թե տեքստ, այլ պատկերներ: PDF-ը նախ պետք է անցնի OCR՝ սկանավորված պատկերները ընթեռնելի տեքստի փոխարկելու համար: AI որոշ գործիքներ ավտոմատ կերպով կառավարում են դա: Եթե ​​ձերն այդպես չէ, ապա սկանավորված PDF-ը տեքստի վրա հիմնված PDF-ի վերափոխելով նախ OCR գործիքի միջոցով հնարավոր է դարձնում ամփոփումը:',
  'faq3-q' => 'Արդյո՞ք անվտանգ է գաղտնի փաստաթղթերը AI-ի ամփոփման գործիք վերբեռնելը:',
  'faq3-a' => 'Սա կախված է ծառայության գաղտնիության քաղաքականությունից: PDFTools-ը ջնջում է բոլոր բեռնված ֆայլերը մեկ ժամ հետո և չի օգտագործում փաստաթղթերի բովանդակությունը AI մոդելների ուսուցման համար: Խիստ գաղտնի փաստաթղթերի համար ստուգեք ցանկացած գործիքի գաղտնիության քաղաքականությունը վերբեռնելուց առաջ: Առցանց գործիքների միջոցով ֆայլերի անվտանգության մասին լրացուցիչ տեղեկությունների համար տես __SAFETY_GUIDE_LINK__ ուղեցույցը:',
  'faq4-q' => 'Կարո՞ղ է AI-ն ամփոփել PDF-ները անգլերենից բացի այլ լեզուներով:',
  'faq4-a' => 'AI-ի հիմնական մոդելները, ներառյալ ChatGPT-ի և Google Gemini-ի ետևում գտնվող մոդելները, աջակցում են շատ լեզուներով ամփոփմանը: Անգլերեն փաստաթղթերի և եվրոպական հիմնական լեզուների համար որակն ամենաբարձրն է, իսկ քիչ տարածված լեզուների համար՝ մի փոքր ավելի ցածր:',
);
